#!/usr/bin/env bash
set -e
echo "Adding background reminder reconciliation for the development build..."

echo "  lib/localNotifications.js"
mkdir -p "$(dirname 'lib/localNotifications.js')"
echo '' | base64 --decode > 'lib/localNotifications.js'

echo "  lib/reminderBackgroundTask.js"
mkdir -p "$(dirname 'lib/reminderBackgroundTask.js')"
echo '' | base64 --decode > 'lib/reminderBackgroundTask.js'

echo "  App.js"
mkdir -p "$(dirname 'App.js')"
echo '' | base64 --decode > 'App.js'

echo "  index.js"
mkdir -p "$(dirname 'index.js')"
echo '' | base64 --decode > 'index.js'

echo "  app.json"
mkdir -p "$(dirname 'app.json')"
echo '' | base64 --decode > 'app.json'

echo "  eas.json"
mkdir -p "$(dirname 'eas.json')"
echo '' | base64 --decode > 'eas.json'

echo ""
echo "Code changes done. Next steps to actually get a development build:"
echo ""
echo "1. Install the new native dependencies (this resolves versions that match"
echo "   your installed Expo SDK automatically):"
echo ""
echo "     npx expo install expo-task-manager expo-background-task expo-dev-client"
echo ""
echo "2. Build a development client. Easiest path (no Mac needed, builds in the"
echo "   cloud) — requires a free Expo account and 'npm install -g eas-cli':"
echo ""
echo "     eas login"
echo "     eas build --profile development --platform android"
echo "     eas build --profile development --platform ios"
echo ""
echo "   Or build locally if you have Android Studio / Xcode installed:"
echo ""
echo "     npx expo run:android"
echo "     npx expo run:ios"
echo ""
echo "3. Install the resulting .apk / .ipa (or simulator build) on your device,"
echo "   then run 'npx expo start --dev-client' and open the app from it — NOT"
echo "   Expo Go, which cannot run this build."
echo ""
echo "You can sanity-check the background task without waiting 15+ min: while the"
echo "dev build is running, call BackgroundTask.triggerTaskWorkerForTestingAsync()"
echo "from a debug button — it only works in dev builds, never in production."
